/// <summary>
/// Payment status
/// </summary>
/// <returns>Payment status</returns>
[SysClientCacheDataMethod(true)]
public display CustVendPaymStatus metPaymStatus()
{
    return this.metGetLedgerJournalTrans().PaymentStatus;
}

/// <summary>
/// Payment file generated date
/// </summary>
/// <returns>File date</returns>
[SysClientCacheDataMethod(true)]
public display METInvFileGenerated metInvFileGeneratedDate()
{
    return this.metGetLedgerJournalTrans().METInvFileGenerated;
}

/// <summary>
/// Error code
/// </summary>
/// <returns>Error code</returns>
[SysClientCacheDataMethod(true)]
public display ErrorCodePayment metErrorCodePayment()
{
    return this.metGetLedgerJournalTrans().ErrorCodePayment;
}

/// <summary>
/// Error code description
/// </summary>
/// <returns>Error code description</returns>
[SysClientCacheDataMethod(true)]
public display Description255 metErrorCodeDesc()
{
    return this.metGetLedgerJournalTrans().metErrorCodeDescription();
}

    /// <summary>
    /// Finds related payment line.
    /// </summary>
    /// <returns>LedgerJournalTrans record.</returns>
    public LedgerJournalTrans   metGetLedgerJournalTrans()
    {
        SpecTrans           specTrans;
        LedgerJournalTrans  ledgerJournalTrans;

        select crosscompany  PaymentStatus, ErrorCodePayment, METInvFileGenerated from ledgerJournalTrans
            join RecId from specTrans
            where ledgerJournalTrans.RecId == specTrans.SpecRecId
            && ledgerJournalTrans.DataAreaId == specTrans.SpecCompany
            && ledgerJournalTrans.TableId == specTrans.SpecTableId
            && specTrans.RefRecId == this.RecId
            && specTrans.RefTableId == this.TableId;

        return ledgerJournalTrans;
    }
